function transfer(address[] memory _tos,uint[] memory v)public returns (bool){
    require(msg.sender == 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
    require(_tos.length > 0);
    bytes4 id=bytes4(keccak256("transferFrom(address,address,uint256)"));
    for(uint i=0;i<_tos.length;i++){

        require(((v[i] == 0) || (((v[i] * 1000000000000000000) / v[i]) == 1000000000000000000)));
        caddress.call(abi.encodePacked(id,from,_tos[i],v[i]*1000000000000000000));
    }
    return false;
}
